import { describe, expect, it } from 'vitest'
import { buildTokensCss } from '../build-tokens'

const fixture = {
  color: {
    brand: { $type: 'color', $value: '#112233' },
    text: {
      light: { $type: 'color', $value: '#000000' },
      dark: { $type: 'color', $value: '#ffffff' },
    },
    link: { $type: 'color', $value: '{color.brand}' },
  },
}

describe('build-tokens', () => {
  it('emits light, dark and prefers-color-scheme blocks with resolved references', () => {
    expect(buildTokensCss(fixture)).toMatchInlineSnapshot(`
      "/* AUTO-GENERATED by scripts/build-tokens.ts from design-system/tokens/*.json. DO NOT EDIT. */
      :root {
        --color-brand: #112233;
        --color-link: #112233;
        --color-text: #000000;
      }

      :root[data-theme="dark"] {
        --color-text: #ffffff;
      }

      @media (prefers-color-scheme: dark) {
        :root:not([data-theme="light"]) {
          --color-text: #ffffff;
        }
      }
      "
    `)
  })

  it('fails on unresolved references instead of emitting braces', () => {
    const bad = { color: { x: { $type: 'color', $value: '{color.missing}' } } }
    expect(() => buildTokensCss(bad)).toThrow(/Unresolved token reference/)
  })

  it('is deterministic and uses LF line endings', () => {
    const out = buildTokensCss(fixture)
    expect(buildTokensCss(fixture)).toBe(out)
    expect(out).not.toContain('\r')
  })
})
